 for(uint32_t i=0;i<original.elements.size()&&!found;++i){const auto&e=original.elements[i];if(original.strings.at(e.type)!="DmeGlobalFlexControllerOperator")continue;uint32_t source=0xffffffffu,model=0xffffffffu;for(uint32_t j=0;j<e.attributes.size();++j){const auto&a=e.attributes[j];auto name=original.strings.at(a.name);if(name=="flexWeight"&&a.type==3)source=j;if(name=="gameModel"&&a.type==1&&a.values.size()==1)model=a.values[0].reference;}if(source==0xffffffffu||model>=original.elements.size())continue;const auto&m=original.elements[model];for(uint32_t j=0;j<m.attributes.size();++j){const auto&a=m.attributes[j];if(original.strings.at(a.name)=="flexWeights"&&a.type==17&&!a.values.empty()){binding={i,source,model,j,0};found=true;break;}}}
